(window.NTDATA=window.NTDATA||{});(NTDATA.cass=NTDATA.cass||{}).mk={"1":{"1":"Начало Евангелия Иисуса Христа, Сына Божия.","2":"Как написано у Исаии пророка: Вот, Я посылаю\nангела Моего пред лицом Твоим, который приготовит\nпуть Твой;","3":"голос вопиющего в пустыне: «приготовьте дорогу\nГосподу, прямыми делайте пути Его».","4":"Был Иоанн Креститель в пустыне, проповедуя\nкрещение покаяния для отпущения грехов.","5":"И выходила к нему вся Иудейская страна и все\nИерусалимляне; и крестились у него в Иордане реке,\nисповедуя грехи свои.","6":"И был Иоанн одет в шерсть верблюжью и пояс\nкожаный на бедрах его, и ел саранчу и дикий мед.","7":"И проповедовал, говоря: идет Сильнейший меня за\nмною, у Которого я недостоин, наклонившись, развязать\nремень обуви Его.","8":"Я крестил вас водою, а Он будет крестить вас\nДухом Святым.","9":"И было в те дни: пришел Иисус из Назарета\nГалилейского и был крещен в Иордане Иоанном.","10":"И\nтотчас,\nвыходя\nиз\nводы,\nувидел\nОн\nразверзающиеся\nнебеса\nи\nДуха,\nкак\nголубя,\nнисходящего на Него.","11":"И\nголос\nраздался\nс\nнебес:\nТы\nСын\nМой\nВозлюбленный, на Тебе Мое благоволение.","12":"И тотчас Дух уводит Его в пустыню.","13":"И был Он в пустыне сорок дней, искушаемый\nсатаною, и был со зверями, и ангелы служили Ему.","14":"И после того, как предан был Иоанн, пришел\nИисус в Галилею, проповедуя Евангелие Божие","15":"и говоря: исполнились сроки, и близко Царство\nБожие; кайтесь и веруйте в Евангелие.","16":"И проходя по берегу моря Галилейского, Он\nувидел Симона и Андрея, брата Симона, закидывающих\nв море сети, ибо они были рыболовы.","17":"И сказал им Иисус: идите за Мною, и Я сделаю\nвас ловцами людей.","18":"И они тотчас оставили сети и последовали за\nНим.","19":"И пройдя немного далее, Он увидел Иакова\nЗеведеева и Иоанна, брата его, тоже в лодке, чинящих\nсети,","20":"и тотчас призвал их. И они оставили отца своего\nЗеведея в лодке с работниками и ушли за Ним.","21":"И входят они в Капернаум. И тотчас, войдя в\nсинагогу в субботу, Он учил.","22":"И изумлялись учению Его, ибо учил Он их, как\nвласть имеющий, а не как книжники.","23":"И человек, бывший в синагоге их, в духе\nнечистом, тотчас вскричал:","24":"что Тебе до нас, Иисус Назарянин? Ты пришел\nпогубить нас! Знаю Тебя, кто Ты, Святой Божий.","25":"И строго сказал ему Иисус: замолчи и выйди из\nнего.","26":"И сведя его судорогой и возгласив громким\nголосом, дух нечистый вышел из него.","27":"И ужаснулись все и спрашивали друг друга: что\nэто такое? Учение новое со властью, и духам нечистым\nОн повелевает, и они повинуются Ему?","28":"И тотчас прошел слух о Нем повсюду по всей\nстране Галилейской.","29":"И тотчас выйдя из синагоги, пришли они в дом\nСимона и Андрея с Иаковом и Иоанном,","30":"Теща же Симона лежала в горячке; и тотчас\nговорят Ему о ней.","31":"И подойдя, Он поднял ее, взяв её руку; и\nоставила ее горячка, и она служила им.","32":"С наступлением же вечера, когда зашло солнце,\nприносили к Нему всех недужных и бесноватых.","33":"И собрался весь город у дверей.","34":"И Он исцелил многих больных различными\nнедугами и многих бесов изгнал и бесам не позволял\nговорить, так как они знали, что Он Христос.","35":"И утром Он вышел, встав задолго до рассвета, и\nушел в пустынное место и там молился.","36":"И поспешил за Ним Симон и бывшие с Ним;","37":"и нашли Его и говорят Ему: все ищут Тебя.","38":"И говорит им: идем в другие ближние селения,\nчтобы Мне и там проповедовать. Ибо для этого Я и\nвышел.","39":"И проповедовал Он в синагогах их по всей\nГалилее, и изгонял бесов.","40":"И приходит к Нему прокаженный, и на коленях\nпросит Его: если Ты хочешь, можешь меня очистить.","41":"И сжалившись, Он протянул руку Свою, коснулся\nего и говорит ему: хочу, очистись.","42":"И тотчас сошла с него проказа, и он очистился.","43":"И строго выговорив ему, Он тотчас отослал его","44":"и говорит ему: смотри, никому ничего не говори,\nно иди, покажись священнику и принеси за очищение\nтвое, что повелел Моисей, во свидетельство им.","45":"А он, выйдя, начал разглашать и распространять\nмолву о происшедшем, так что Ему уже нельзя было\nявно войти в город, но был Он вне города, в местах\nпустынных. И приходили к Нему отовсюду."},"2":{"1":"И когда через некоторое время Он снова вошел в\nКапернаум, стало известно, что Он – дома.","2":"И собрались многие, так что и у двери уже не\nбыло места, и Он говорил им слово,","3":"И пришли, неся к Нему расслабленного, которого\nдержали на руках четверо;","4":"и так как не могли донести до Него из-за толпы,\nто раскрыли кровлю, где Он был, и, прокопав, спускают\nкровать, на которой лежал расслабленный.","5":"И увидев веру их, говорит Иисус расслабленному:\nчадо, прощаются грехи твои.","6":"Сидели же здесь кое-кто из книжников и\nрассуждали в сердцах своих:","7":"что Он так говорит? Богохульствует! Кто может\nпрощать грехи, кроме одного Бога?","8":"И тотчас узнав Иисус духом Своим, что они так\nрассуждают в себе, говорит им: что это вы рассуждаете\nв сердцах ваших?","9":"Что\nлегче?\nСказать\nли\nрасслабленному:\n«прощаются грехи твои», или сказать: «встань и возьми\nкровать твою и ходи»?","10":"Но, чтобы вы знали, что власть имеет Сын\nЧеловеческий прощать грехи на земле, – говорит\nрасслабленному:","11":"тебе говорю, встань, возьми кровать твою и иди в\nдом твой.","12":"он встал и, тотчас взяв кровать, вышел перед\nвсеми, так что изумлялись все и прославляли Бога,\nговоря: мы никогда ничего подобного не видели.","13":"И Он вышел снова на берег моря, и весь народ\nшел к Нему, и Он учил их.","14":"И проходя, увидел Левия Алфеева, сидящего у\nсбора пошлин, и говорит ему: следуй за Мною. И он\nвстал и последовал за Ним.","15":"И вот, возлежит Он в доме его, и многие мытари\nи грешники возлежали с Иисусом и учениками Его –\nбыло их много, и они следовали за Ним.","16":"И книжники из фарисеев, увидев, что Он ест с\nгрешниками и мытарями, говорили ученикам Его:\nпочему Он ест с мытарями и грешниками?","17":"И услышав, Иисус говорит им: не здоровым\nнужен врач, а болящим. Я пришел призвать не\nправедных, но грешных.","18":"И постились ученики Иоанновы и фарисеи. И\nприходят и говорят Ему: почему ученики Иоанновы и\nученики\nфарисеев\nпостятся,\nа\nТвои\nученики\nне\nпостятся?","19":"И сказал им Иисус: могут ли сыны чертога\nбрачного поститься в то время, когда с ними Жених?\nПока Жених с ними, не могут поститься.","20":"Придут же дни, когда взят будет от них Жених, и\nтогда будут поститься в тот день.","21":"Никто не пришивает заплаты из новой ткани к\nветхой одежде; иначе пришитое ее разорвет: новое\nразорвет старое, и дыра будет хуже.","22":"И никто не наливает вино молодое в мехи\nветхие: иначе прорвет вино мехи, и вино пропадает и\nмехи; но вино молодое наливают в мехи новые.","23":"И\nслучилось\nЕму\nв\nсубботу\nпроходить\nзасеянными полями; и ученики Его начали дорогой\nсрывать колосья.","24":"И фарисеи говорили Ему: посмотри! Что это они\nделают в субботу, чего нельзя!","25":"И Он говорит им: вы никогда не читали, что\nсделал Давид, когда имел нужду и проголодался сам и\nсопровождавшие Его?","26":"Как он вошел в дом Божий при Авиафаре\nпервосвященнике и съел хлебы предложения, которых\nнельзя есть никому, кроме священников, но дал и\nбывшим с ним.","27":"И говорил им: суббота создана для человека, а не\nчеловек для субботы;","28":"так что Сын Человеческий есть господин и\nсубботы."},"3":{"1":"И снова вошел Он в синагогу, и был там человек с\nиссохшей рукой.","2":"И наблюдали за Ним, не исцелит ли его в субботу,\n– чтобы обвинить Его.","3":"И\nговорит\nчеловеку\nс\nсухою\nрукой:\nстань\nпосредине.","4":"И говорит им: дозволяется ли в субботу доброе\nсделать или злое? Душу спасти или убить? Они\nмолчали.","5":"И обведя их гневным взором, в скорби об\nогрубении сердца их, говорит человеку: протяни руку\nтвою. И он протянул, и восстановилась рука его.","6":"И выйдя, фарисеи тотчас же вместе с иродианами\nвынесли против Него решение, чтобы погубить Его.","7":"И Иисус с учениками своими удалился к морю, и\nследом пошло многое множество из Галилеи, и из\nИудеи,","8":"и из Иерусалима, и из Идумеи, и из-за Иордана, и\nиз окрестностей Тира и Сидона. Многое множество,\nуслышав о всём, что Он творит, пришло к Нему.","9":"И сказал ученикам Своим, чтобы лодка была для\nНего наготове из-за толпы, чтобы не теснили Его.","10":"Ибо многих Он исцелил, так что все, кто имел\nнедуги, кидались к Нему, чтобы дотронуться до Него.","11":"И духи нечистые, когда Его видели, падали\nперед Ним и кричали: Ты – Сын Божий.","12":"И весьма строго требовал Он от них не\nразглашать о Нем.","13":"И Он поднимается на гору и призывает к Себе,\nкого Сам хотел. И они пошли к Нему.","14":"И поставил двенадцать, чтобы были с Ним, и\nчтобы посылать их проповедовать,","15":"и иметь им власть изгонять бесов.","16":"И поставил этих двенадцать, и дал имя Симону –\nПетр;","17":"и Иакова Зеведеева и Иоанна, брата Иакова, и\nдал им имя Боанергос, то есть «сыны грома»;","18":"и Андрея, и Филиппа, и Варфоломея, и Матфея, и\nФому, и Иакова Алфеева, и Фаддея, и Симона Кананита,","19":"и Иуду Искариота, который и предал Его.","20":"И приходит в дом, и сходится снова толпа, так\nчто они не могли даже поесть.","21":"И услышав, близкие Его вышли взять Его; они\nговорили: Он – вне Себя.","22":"И\nкнижники,\nпришедшие\nиз\nИерусалима,\nговорили: в Нем Веельзевул, и Он изгоняет бесов силою\nкнязя бесовского.","23":"И призвав их, в притчах говорил им: как может\nсатану изгонять сатана?","24":"Если царство будет разделено внутреннею\nвраждой, не может устоять царство то;","25":"если дом будет разделен внутреннею враждой,\nне сможет дом тот устоять;","26":"и если сатана восстал на самого себя и\nразделился, не может он устоять, но пришел конец его.","27":"Но не может никто, войдя в дом сильного,\nрасхитить его вещи, если прежде не свяжет сильного, и\nтогда он расхитит дом его.","28":"Истинно говорю вам: всё будет прощено сынам\nчеловеческим: грехи и хулы, какими бы ни похулили;","29":"кто же произнесет хулу на Духа Святого, нет ему\nпрощения вовек, но повинен он в вечном грехе","30":"(потому что они говорили: в Нем дух нечистый).","31":"И приходят Матерь Его и братья Его и, стоя\nснаружи, послали к Нему позвать Его.","32":"И окружал Его народ. И говорят Ему: вот, Матерь\nТвоя и братья Твои снаружи, ищут Тебя.","33":"И Он им ответил: кто матерь Моя и братья Мои?","34":"И обведя взором сидящих вокруг Него, говорит:\nвот матерь Моя и братья Мои;","35":"ибо кто исполнит волю Божию, тот брат Мой и\nсестра и матерь."},"4":{"1":"И снова начал Он учить у берега моря; и\nсобирается к Нему толпа весьма многолюдная, так что\nОн, войдя в лодку, был на море, а вся толпа на земле у\nморя.","2":"И учил Он их в притчах многому и говорил им в\nучении Своем:","3":"слушайте, вот, вышел сеятель сеять.","4":"И было: когда он сеял, иное семя упало при\nдороге, и прилетели птицы и поклевали его.","5":"И другое упало на камень, где у него немного\nбыло земли, и тотчас взошло, ибо земля у него не была\nглубока;","6":"и когда взошло солнце, было опалено и, не имея\nкорня, засохло.","7":"И другое упало в терние, и поднялось терние и\nзаглушило его, и плода оно не дало.","8":"И другие упали на землю добрую и давали плод,\nподнимаясь и возрастая, и приносили по тридцати и по\nшестидесяти и по ста.","9":"И говорил им: кто имеет уши слышать, да слышит!","10":"И когда Он оказался один, стали спрашивать Его\nокружающие вместе с Двенадцатью о притчах.","11":"И говорил им: вам дана тайна Царства Божия,\nтем же внешним всё бывает в притчах,","12":"чтобы они глазами глядели и не увидели, и\nслухом слышали и не уразумели, чтобы не обратились\nони, и не было прощено им.","13":"И говорит им: не постигаете этой притчи? Как же\nвы поймете все притчи?","14":"Сеятель сеет слово.","15":"И вот те, что при дороге, где сеется слово: когда\nони услышат, тотчас приходит сатана и уносит слово,\nпосеянное в них.","16":"А вот подобным же образом и те, что сеются на\nкамне: они, когда услышат слово, тотчас с радостью\nпринимают его,","17":"но не имеют корня в себе и держатся короткое\nвремя; потом с наступлением скорби или гонения за\nслово, тотчас соблазняются.","18":"И вот другие, те, что сеются в тернии: это –\nуслышавшие слово,","19":"и заботы века и обольщение богатства и прочие\nвожделения, входя, заглушают слово, и оно делается\nбесплодным.","20":"А вот и те, что на земле доброй посеяны: они\nслышат слово и принимают и дают плод по тридцати и\nпо шестидесяти и по ста.","21":"И говорил им: разве для того приносится\nсветильник, чтобы поставить его под сосуд или под\nкровать? Не для того ли, чтобы поставить его на\nподсвечник?","22":"Ведь, если что скрыто, то лишь для того, чтобы\nбыть обнаруженным, и сокровенным оно стало только\nдля того, чтобы выйти наружу.","23":"Если кто имеет уши слышать, да слышит.","24":"И говорил им: замечайте, что слышите: какою\nмерой мерите, такою будут мерить вам, и будет\nприбавлено вам.","25":"Ибо кто имеет, тому будет дано, и кто не имеет,\nу того будет взято и то, что имеет.","26":"И говорил: таково Царство Божие: оно подобно\nчеловеку, который бросит семя в землю,","27":"и спит и встает, ночью и днем, а семя всходит и\nтянется вверх, он сам не знает как;","28":"земля сама собой дает плод: сперва зелень,\nпотом колос, потом полное зерно в колосе;","29":"когда же созреет плод, он тотчас посылает серп,\nпотому что настала жатва.","30":"И говорил: каким подобием выразить нам\nЦарство Божие? Или в какой притче представить его?","31":"Подобием зерна горчичного. Когда его посеют в\nземлю, оно, самое маленькое из всех семян на земле,","32":"поднимается и становится больше всех овощей и\nпускает большие ветви, так что птицы небесные могут\nвить гнёзда под тенью его.","33":"И такими многими притчами Он говорил им,\nнасколько они могли слышать.","34":"Без притчи же им не говорил, но ученикам Своим\nотдельно от других объяснял всё.","35":"И говорит им в тот день, когда вечер настал:\nпереправимся на ту сторону.","36":"И они, оставив народ, берут Его с собой, как Он\nбыл в лодке; и другие лодки были с Ним.","37":"И поднимается сильный вихрь; и волны били в\nлодку, так что лодка уже наполнялась водой.","38":"А Он спал на корме на изголовье. И будят Его и\nговорят Ему: Учитель, Тебе всё равно, что мы погибаем?","39":"И проснувшись, Он возбранил ветру и сказал\nморю: молчи, стихни. И прекратился ветер, и настала\nтишина великая.","40":"И сказал им: что вы так боязливы? Как у вас нет\nверы?","41":"И они устрашились страхом великим и говорили\nдруг другу: кто же Он, что и ветер и море повинуются\nЕму?"},"5":{"1":"И прибыли на другой берег моря в страну\nГерасинскую.","2":"И когда высадился Он из лодки, тотчас вышел к\nНему\nнавстречу\nиз\nмогильных\nпещер\nчеловек,\nодержимый духом нечистым,","3":"Жилище его было в могильных пещерах, и никто\nеще не мог связать его даже цепью:","4":"потому\nчто\nон\nмногократно\nбывал\nсвязан\nкандалами и цепями, но разрывал цепи и разбивал\nкандалы, и никто не в силах был его укротить;","5":"и всегда, ночью и днем, в могильных пещерах и в\nгорах, он кричал и бил себя камнями.","6":"И увидев Иисуса издалека, он прибежал и\nпоклонился Ему,","7":"и закричал громким голосом: что Тебе до меня,\nИисус, Сын Бога Всевышнего? Заклинаю Тебя Богом, не\nмучь меня.","8":"Ибо Он говорил ему: выйди, дух нечистый, из\nэтого человека.","9":"И спрашивал его: как имя тебе? И он говорит Ему:\nлегион имя мне, потому что нас много,","10":"И просил Его, чтобы не высылал их вон из этой\nстраны.","11":"Паслось же там при горе большое стадо свиней.","12":"И попросили Его: пошли нас в свиней, чтобы нам\nвойти в них.","13":"И позволил им. И выйдя, духи нечистые вошли в\nсвиней; и ринулось стадо – около двух тысяч голов – с\nкрутизны в море, и тонули в море.","14":"И пастухи побежали и объявили в городе и в\nдеревнях. И люди пришли посмотреть, что такое\nслучилось.","15":"И приходят к Иисусу и видят, что бесноватый\nсидит, одетый и в здравом уме, тот, в котором был\nлегион, и устрашились.","16":"И рассказали им видевшие, как это произошло с\nбесноватым, и о свиньях.","17":"И начали просить Его уйти из области их.","18":"И когда входил Он в лодку, тот, кто некогда\nбесновался, просил Его, чтобы быть с Ним.","19":"И Он не допустил его, но говорит ему: иди в дом\nтвой, к твоим, и возвести им, что сделал тебе Господь и\nкак помиловал тебя.","20":"И\nон\nпошел\nи\nначал\nпроповедовать\nв\nДесятиградии, что сделал ему Иисус. И все удивлялись.","21":"И когда переправился Иисус в лодке снова на\nдругую сторону, собралось много народа вокруг Него, и\nбыл Он на берегу моря.","22":"И приходит один из начальников синагоги, по\nимени Иаир, и увидев Его, падает к ногам Его","23":"и умоляет Его, говоря: дочка моя при смерти.\nТолько бы Ты пришел и возложил руки на нее, чтобы\nона была спасена и осталась жива!","24":"И Он пошел с ним, и следовало за Ним много\nнарода, и теснили Его.","25":"И\nженщина,\nстрадавшая\nкровотечением\nдвенадцать лет,","26":"много\nпретерпевшая\nот\nмногих\nврачей,\nистратившая всё, что у нее было, и не получившая\nникакой\nпользы,\nно\nдаже\nпришедшая\nв\nхудшее\nсостояние,","27":"услышав об Иисусе, подошла в толпе сзади и\nприкоснулась к одежде Его.","28":"Ибо она говорила: если прикоснусь хотя бы к\nодеждам Его, буду спасена;","29":"и тотчас высох источник крови ее, и она ощутила\nв теле, что исцелена от недуга.","30":"И почувствовав тотчас в Самом Себе, что из Него\nвышла сила, Иисус повернулся в толпе и спросил: кто\nприкоснулся к Моим одеждам?","31":"И говорили Ему ученики Его: Ты видишь, что\nтолпа теснит Тебя, и говоришь: «кто прикоснулся ко\nМне?»","32":"И Он смотрел вокруг, чтобы увидеть ту, которая\nэто сделала,","33":"Женщина же, испуганная и дрожащая, зная, что\nпроизошло с ней, подошла и пала перед Ним на землю и\nсказала Ему всю истину.","34":"Он же сказал ей: дочь Моя! Вера твоя спасла\nтебя. Иди с миром и будь здорова, избавившись от\nнедуга твоего.","35":"Пока Он еще говорил, приходят от начальника\nсинагоги и говорят: дочь твоя умерла; что еще\nутруждаешь Учителя?","36":"Иисус же, уловив это слово налету, говорит\nначальнику синагоги: не бойся, только веруй.","37":"И не допустил никого последовать вместе с Ним,\nкроме Петра, Иакова и Иоанна, брата Иакова.","38":"И приходят в дом начальника синагоги, и видит\nОн смятение и плачущих и громко причитающих.","39":"И войдя, говорит им: что смущаетесь и плачете?\nДитя не умерло, но спит.","40":"И смеялись над Ним. Он же, удалив всех, берет с\nСобой отца ребенка и мать и бывших с Ним и входит\nтуда, где было дитя.","41":"И взяв ребенка за руку, говорит: талифа кум, что\nв переводе значит: отроковица, тебе говорю, встань.","42":"И тотчас встала девочка и начала ходить; была\nона лет двенадцати. И изумились тотчас изумлением\nвеликим.","43":"И повелел им настоятельно, чтобы никто не\nузнал об этом, и сказал, чтобы дали ей есть."},"6":{"1":"И вышел Он оттуда и приходит в отечество Свое; и\nследуют за Ним ученики Его.","2":"И когда настала суббота, начал Он учить в\nсинагоге, и многочисленные слушатели изумлялись и\nговорили: откуда у Него это? И что это за премудрость\nдана Ему? И такие чудеса совершаются руками Его!","3":"Не Он ли плотник, сын Марии и брат Иакова,\nИосита, Иуды и Симона? И сестры Его не здесь ли с\nнами? И соблазнялись из-за Него.","4":"И говорил им Иисус: не бывает пророк без чести,\nразве только в отечестве своем и между сродниками\nсвоими и в доме своем.","5":"И не мог сотворить там ни одного чуда, только на\nнемногих больных возложил руки и исцелил их.","6":"И удивился неверию их. И обходил Он окрестные\nселения, уча.","7":"И призывает Двенадцать. И начал посылать их по\nдва и давал им власть над духами нечистыми.","8":"И повелел им ничего не брать в дорогу, только\nпосох: ни хлеба, ни сумы, ни меди в пояс.","9":"Но обуваться в сандалии и не надевать двух\nрубашек.","10":"И говорил им: куда бы вы ни вошли в дом, там\nоставайтесь, пока не выйдете оттуда.","11":"И если в каком месте не примут вас, и не\nпослушают вас, – выходя оттуда, стряхните пыль с\nподошв ваших во свидетельство им.","12":"И выйдя оттуда, они проповедали покаяние.","13":"И многих бесов изгоняли и мазали маслом многих\nбольных и исцеляли.","14":"И услышал то царь Ирод, – ибо стало известно\nимя Его, и говорили: Иоанн Креститель восстал из\nмертвых, и потому в нем действуют силы.","15":"Другие же говорили: это Илия. А другие\nговорили: это пророк, как и другие пророки.","16":"А Ирод, услышав это, говорил: Иоанн, которого я\nобезглавил, – он и восстал.","17":"Ибо Ирод послал взять Иоанна и заключить его\nсвязанного в тюрьму из-за Иродиады, жены Филиппа,\nбрата своего, потому что женился на ней.","18":"Ибо Иоанн говорил Ироду: нельзя тебе иметь\nжену брата твоего.","19":"Иродиада же питала к нему вражду и хотела его\nубить, но не могла.","20":"Ибо Ирод боялся Иоанна, зная, что он муж\nправедный и святой, и берёг его; и выслушав его,\nсмущался сильно, и охотно слушал его.","21":"И удобный день настал, когда Ирод, по случаю\nдня своего рождения, сделал пир для вельмож своих и\nтысяченачальников и сановных людей Галилеи, –","22":"и вошла тогда дочь Иродиады и проплясала: и\nугодила она Ироду и возлежащим с ним. И сказал царь\nдевице: проси у меня, чего хочешь, и дам тебе.","23":"И поклялся ей: чего ни попросишь, дам тебе, – до\nполовины царства моего.","24":"И выйдя, она сказала матери своей: что\nпопросить\nмне?\nА\nта\nсказала:\nголову\nИоанна\nКрестителя.","25":"И войдя тотчас с поспешностью к царю, она\nпопросила его: хочу, чтобы ты сейчас же дал мне на\nблюде голову Иоанна Крестителя.","26":"И объятый скорбью царь, ради клятвы и\nвозлежащих, не захотел отказать ей.","27":"И тотчас же, послав телохранителя, царь\nприказал\nпринести\nголову\nего.\nИ\nтот\nпошел\nи\nобезглавил его в тюрьме","28":"и принес голову его на блюде и дал ее девице, а\nдевица дала ее матери своей.","29":"И услышав, ученики его пришли и взяли тело его\nи положили в могилу.","30":"И собираются апостолы к Иисусу. Они рассказали\nЕму всё, что сделали и чему научили.","31":"И Он говорит им: пойдите вы сами, отдельно от\nдругих, в пустынное место и отдохните немного. Ибо\nприходило и уходило много народа и даже поесть у них\nне было времени.","32":"И отплыли они в лодке в пустынное место\nотдельно от других.","33":"И увидели, что они удаляются, и узнали об этом\nмногие, и пешие из всех городов сбежались туда и\nпришли раньше их.","34":"И выйдя, Он увидел много народа и сжалился\nнад ними, потому что они были, как овцы, не имеющие\nпастыря; и начал учить их много.","35":"И когда уже наступил поздний час, подошли к\nНему ученики Его и говорили: пустынно это место, и час\nуже поздний;","36":"отпусти их, чтобы они пошли в окрестные\nдеревни и селения и купили себе поесть.","37":"Он же ответил им: дайте им вы поесть. И говорят\nЕму: не пойти ли нам купить хлебов динариев на двести\nи дать им есть?","38":"Он же говорит им: сколько у вас хлебов? Идите,\nпосмотрите. И узнав, они говорят: пять, и две рыбы.","39":"И приказал им, чтобы все расположились\nкружками на зеленой траве.","40":"И возлегли они рядами по ста и по пятидесяти.","41":"И взяв эти пять хлебов и эти две рыбы, поднял\nОн глаза к небу, благословил и преломил хлебы и давал\nученикам, чтобы они разносили им; и две рыбы\nразделил на всех.","42":"И ели все и насытились.","43":"И кусков собрали двенадцать коробов полных, и\nостатки от рыб;","44":"и было евших хлебы пять тысяч мужчин.","45":"И тотчас заставил Он учеников Своих войти в\nлодку и переправиться теперь же на другую сторону к\nВифсаиде, пока Он отпускает народ.","46":"И простившись с ними, ушел на гору помолиться.","47":"И когда настал вечер, лодка была посредине\nморя, а Он один на земле.","48":"И увидев, что они гребут через силу – ветер им\nбыл противный, – около четвертой стражи ночи идет Он\nк ним, ступая по морю. И хотел миновать их.","49":"Они же, увидев, что Он ступает по морю,\nподумали, что это призрак, и подняли крик.","50":"Ибо все видели Его и были смущены. Он же\nтотчас заговорил с ними и сказал им: мужайтесь, это Я,\nне бойтесь.","51":"И вошел к ним в лодку; и прекратился ветер. И\nони чрезвычайно про себя изумлялись.","52":"Ибо не вразумились они хлебами, но огрубело их\nсердце.","53":"И переправившись, они достигли земли в\nГеннисарете и пристали к берегу.","54":"И когда они вышли из лодки, люди, тотчас узнав\nЕго,","55":"обежали всю страну ту и начали на кроватях\nприносить болящих туда, где, как слышно было, Он\nнаходился.","56":"И, куда бы Он ни входил, в селения, или в города,\nили в деревни, клали больных на площадях и просили\nЕго, чтобы им хоть к краю одежды Его прикоснуться, и\nкто бы ни прикоснулся к Нему, все спасались."},"7":{"1":"И сходятся к Нему фарисеи и некоторые из\nкнижников, пришедшие из Иерусалима.","2":"И увидев, что некоторые из учеников Его едят\nхлеб нечистыми, то есть неумытыми, руками,","3":"(ибо фарисеи и все Иудеи, если установленным\nобразом не умоют рук, не едят, держась предания\nстарцев;","4":"и придя с рынка, если не окропятся, не едят; есть\nи\nмногое\nдругое,\nчего\nони\nприняли\nдержаться:\nомовения чаш и кружек и медной посуды), –","5":"спрашивают Его фарисеи и книжники: почему не\nпоступают ученики Твои по преданию старцев, но\nнечистыми руками едят хлеб?","6":"Он же сказал им: хорошо пророчествовал Исаия о\nвас лицемерах, как написано: «Этот народ устами Меня\nчтит, сердце же их далеко отстоит от Меня;","7":"но тщетно воздают Мне почитание, уча учениям,\nпредписаниям человеческим».","8":"Оставив заповедь Божию, вы держитесь предания\nчеловеческого.","9":"И говорил им: отменять заповедь Божию, чтобы\nпредание ваше соблюсти, это вы умеете,","10":"Моисей, ведь, сказал: «Почитай отца твоего и\nматерь твою»; и: «Злословящий отца или мать смертью\nда умрет».","11":"Вы же говорите: если скажет человек отцу или\nматери: «корван (то есть дар) то, чем бы ты от меня\nвоспользовался», –","12":"вы позволяете ему уже ничего не делать для\nотца или матери,","13":"отменяя слово Божие преданием вашим, которое\nчерез вас же и идет. И много подобного в этом роде вы\nделаете.","14":"И призвав снова народ, говорил им: послушайте\nМеня все и уразумейте.","15":"Ничто, входящее в человека извне, не может\nосквернить его; но то, что исходит из человека, то\nоскверняет человека.","16":"Стих 16 прежних русских переводов: «Если кто\nимеет уши слышать, да слышит!» отсутствует в\nдревнейших рукописях Мк.","17":"И когда Он оставил толпу и вошел в дом,\nспрашивали Его ученики Его о притче.","18":"И Он говорит им: неужели и вы еще не\nразумеете? Не понимаете, что ничто, извне входящее в\nчеловека, не может осквернить его?","19":"Потому что входит не в его сердце, но в чрево и\nвыходит вон (тем самым Он объявляет чистой всякую\nпищу).","20":"Он говорил: то, что из человека исходит, то\nоскверняет человека;","21":"изнутри, ведь, из сердца людей, злые мысли\nисходят, блудодеяния, кражи, убийства,","22":"прелюбодеяния, хищения, лукавства, коварство,\nраспутство, глаз лукавый, хула, гордость, безумство.","23":"Всё это зло изнутри исходит и оскверняет\nчеловека.","24":"И встав, Он пошел оттуда в область Тира и\nСидона. И войдя в дом, хотел, чтобы никто не узнал; и\nне мог укрыться.","25":"Но, тотчас услышав о Нем, женщина, дочка\nкоторой имела духа нечистого, пришла и упала к ногам\nЕго –","26":"а женщина была язычница, Сирофиникиянка\nродом – и просила Его изгнать беса из дочери ее.","27":"И Он говорил ей: дай прежде насытиться детям;\nнехорошо, ведь, взять хлеб у детей и бросить собакам.","28":"Она же ответила Ему: да, Господи; и собаки едят\nпод столом крошки у детей.","29":"И сказал Он ей: за это слово, иди; вышел из\nтвоей дочери бес.","30":"И уйдя в дом свой, она нашла, что дитя лежит на\nпостели, и что бес вышел.","31":"И снова выйдя из области Тира, Он пришел через\nСидон к морю Галилейскому в области Десятиградия.","32":"И приводят к Нему глухого и косноязычного и\nпросят Его возложить на него руку.","33":"И отведя его в сторону от толпы и оставшись с\nним наедине, Он вложил пальцы Свои в уши его и,\nплюнув, коснулся языка его;","34":"и подняв глаза к небу, тяжело вздохнул и\nговорит ему: эффафа, то есть откройся.","35":"И открылись его уши, и тотчас разрешились узы\nязыка его, и он стал говорить правильно.","36":"И приказал Он им, чтобы никому не говорили. Но\nчем больше приказывал, тем больше они разглашали.","37":"И чрезвычайно изумлялись, говоря: хорошо Он\nвсё сделал: и глухим дает слышать и немым говорить."},"8":{"1":"В те дни, когда снова было много народа, и им\nнечего было есть, Он, призвав учеников, говорит им:","2":"жаль Мне народа, уже три дня остаются они со\nМной, и нечего им есть;","3":"и\nесли\nотпущу\nих\nнеевшими\nдомой,\nони\nобессилеют в дороге, а некоторые из них пришли\nиздалека.","4":"И ответили Ему ученики Его: как насытить их\nхлебами здесь, в пустыне?","5":"И Он спрашивал их: сколько у вас хлебов? Они\nсказали: семь.","6":"И повелевает толпе возлечь на землю; и взяв эти\nсемь хлебов, воздав благодарение, преломил и давал\nученикам Своим, чтобы они разносили; и они разнесли\nнароду.","7":"И было у них немного рыбок; и благословив их. Он\nвелел разносить и их.","8":"И ели и насытились, и собрали оставшихся кусков\nсемь корзин.","9":"А было их около четырех тысяч. И Он отпустил их.","10":"И тотчас войдя в лодку с учениками Своими,\nприбыл в пределы Далмануфские.","11":"И вышли фарисеи и начали спорить с Ним, требуя\nот Него знамения с неба, искушая Его.","12":"И восстенав в духе Своем, Он говорит: почему\nрод этот требует знамения? Истинно говорю вам, не\nбудет дано роду этому знамения.","13":"И оставив их, Он снова сел в лодку и отбыл на\nдругую сторону.","14":"И забыли они взять хлебы, и только один хлеб\nбыл у них с собой в лодке.","15":"И Он наказывал им: смотрите, берегитесь\nзакваски фарисейской и закваски Иродовой.","16":"И рассуждали между собой, что хлебов у них нет.","17":"И узнав это, Он говорит им: что рассуждаете о\nтом, что нет у вас хлебов? Всё еще не понимаете и не\nразумеете? Огрубело ваше сердце?","18":"Глаза имея, не видите? И уши имея, не слышите?\nИ разве не помните:","19":"когда Я те пять хлебов преломил для пяти тысяч,\nсколько коробов, полных кусками, вы собрали? Говорят\nЕму: двенадцать.","20":"А когда те семь для четырех тысяч, в скольких\nкорзинах вы собрали оставшиеся куски? Говорят: в\nсеми.","21":"И Он сказал им: вы всё еще не разумеете?","22":"И приходят в Вифсаиду; и приводят к Нему\nслепого и просят Его прикоснуться к нему.","23":"И взяв слепого за руку, Он вывел его из селения\nи, плюнув на глаза его, возложил на него руки и\nспрашивал: видишь ли ты что-нибудь?","24":"И посмотрев, тот говорит: вижу людей, потому\nчто различаю как бы деревья, но они ходят.","25":"Потом Он снова возложил руки на глаза его, и\nтот посмотрел пристально и исцелился и стал видеть\nясно всё.","26":"И Он отправил его в дом его, говоря: даже и в\nселение не входи.","27":"И пошел Иисус и ученики Его в селения Кесарии\nФилипповой. И дорогою Он спрашивал учеников Своих:\nза кого Меня почитают люди?","28":"Они сказали Ему: за Иоанна Крестителя, а другие\n– за Илию, другие же говорят: это один из пророков.","29":"И спрашивал Он их: а вы за кого Меня почитаете?\nИ отвечает Ему Петр: Ты – Христос.","30":"И строго наказал им никому не говорить о Нем.","31":"И\nначал\nучить\nих,\nчто\nнадлежит\nСыну\nЧеловеческому много претерпеть и быть отвергнутым\nстарейшинами и первосвященниками и книжниками, и\nбыть убитым, и через три дня воскреснуть.","32":"И это слово Он говорил открыто. И отозвав Его,\nПетр начал Ему выговаривать.","33":"Он же, обернувшись и увидев учеников Своих,\nстрого укорил Петра и говорит: прочь! За Мною, сатана,\nпотому что думаешь ты не о Божьем, но о человеческом.","34":"И призвав народ вместе с учениками Своими,\nсказал им: если кто хочет за Мною пойти, да отречется\nот самого себя и возьмет крест свой и следует за Мною.","35":"Ибо, кто хочет душу свою спасти, тот погубит ее;\nкто же погубит душу свою ради Меня и Евангелия, тот\nспасет ее.","36":"Ибо какая выгода человеку весь мир приобрести\nи повредить душе своей?","37":"Ибо что даст человек в обмен за душу свою?","38":"Ибо, кто постыдится Меня и Моих слов в роде\nэтом прелюбодейном и грешном, того постыдится и Сын\nЧеловеческий, когда придет во славе Отца Своего с\nангелами святыми."},"9":{"1":"И Он говорил им: истинно говорю вам: есть\nнекоторые из стоящих здесь, которые не вкусят смерти,\nдоколе не увидят Царства Божия, пришедшего в силе.","2":"И через шесть дней берет Иисус Петра, Иакова и\nИоанна, и отдельно от других возводит на гору\nвысокую, их одних. И преобразился Он перед ними:","3":"и одежды Его сделались блистающими, белыми\nвесьма, такими, что белильщик на земле не может так\nвыбелить.","4":"И явились им Илия с Моисеем и беседовали с\nИисусом.","5":"И сказал Петр Иисусу: Равви, хорошо нам здесь\nбыть, сделаем три шатра: Тебе один, и Моисею один, и\nИлии один.","6":"Ибо не знал он, что сказать, ибо объял их страх.","7":"И появилось облако, осеняющее их, и раздался\nголос из облака: это – Сын Мой Возлюбленный:\nслушайте Его.","8":"И внезапно, посмотрев вокруг, они больше никого\nне увидели, кроме одного Иисуса с ними.","9":"И когда сходили они с горы, Он приказал им\nникому не рассказывать о том, что видели, пока Сын\nЧеловеческий не воскреснет из мертвых,","10":"И это слово они удержали, рассуждая между\nсобой, что значит: «когда Он воскреснет из мертвых».","11":"И спрашивали Его: почему же книжники говорят,\nчто Илии надлежит придти прежде?","12":"И Он сказал им: правда, что Илия должен придти\nпрежде и восстановить всё. А как же написано о Сыне\nЧеловеческом, что надлежит Ему много пострадать и\nбыть уничиженным?","13":"Но говорю вам, что и Илия пришел, и сделали с\nним всё, что им хотелось, как написано о нем.","14":"И придя к ученикам, увидели много народа\nвокруг них и книжников, спорящих с ними.","15":"И тотчас весь народ, увидев Его, изумился, и\nлюди, подбегая, приветствовали Его.","16":"И Он спросил их: о чем вы спорите с ними?","17":"И ответил Ему один из толпы: Учитель, я привел\nк Тебе сына моего, имеющего духа немого.","18":"И где он на него ни нападет, бросает его на\nземлю, и он испускает пену и скрежещет зубами и\nкоченеет; и сказал я ученикам Твоим, чтобы изгнали\nего, и они не смогли.","19":"И Он ответил им: о, род неверный! Доколе с вами\nбуду? Доколе буду выносить вас? Приведите его ко Мне.","20":"И привели его к Нему. И увидев Его, дух тотчас\nсвел его сильной судорогой; и упав на землю, он\nкатался, испуская пену.","21":"И Иисус спросил отца его: сколько времени, как\nэто случилось с ним? Он же сказал: с детства.","22":"И часто в огонь бросал его дух и в воду, чтобы\nпогубить его; но, если что можешь, помоги нам,\nсжалься над нами.","23":"Иисус же сказал ему: ты сказал – «если что\nможешь». Всё возможно верующему.","24":"И тотчас вскричал отец ребенка: верую, помоги\nмоему неверию.","25":"Иисус же увидев, что сбегается толпа, возбранил\nдуху нечистому, говоря ему: дух немой и глухой! Я\nповелеваю тебе, выйди из него и более не входи в него.","26":"И вскрикнув и сильно сведя его судорогой, дух\nвышел; и сделался он, как мертвый, так что многие\nговорили: умер.","27":"Иисус же, взяв его за руку, поднял его, и он\nвстал.","28":"И когда вошел Иисус в дом, ученики Его\nотдельно от других спрашивали Его: почему мы не\nсмогли изгнать его?","29":"И Он сказал им: этот род ничем не может быть\nизгнан: только молитвой.","30":"И выйдя оттуда, они проходили через Галилею; и\nОн не хотел, чтобы кто узнал.","31":"Ибо Он давал наставления Своим ученикам и\nговорил им, что Сын Человеческий будет предан в руки\nчеловеческие, и убьют Его, и, убитый, Он через три дня\nвоскреснет.","32":"Но они не понимали этого слова и боялись Его\nспросить.","33":"И пришли в Капернаум; и уже в доме Он\nспрашивал их: что вы дорогой обсуждали?","34":"Они же молчали. Ибо дорогой они обсуждали\nмежду собой: кто больше?","35":"И сев, позвал Двенадцать и говорит им: если кто\nхочет быть первым, пусть будет из всех последним и\nвсем слугой.","36":"И взяв дитя, Он поставил его посреди них и,\nобняв его, сказал им:","37":"кто одного из таких детей примет во имя Мое,\nМеня принимает, и кто Меня принимает, не Меня\nпринимает, но Пославшего Меня.","38":"Сказал Ему Иоанн: Учитель! Мы видели человека,\nименем Твоим изгоняющего бесов, и препятствовали\nему, потому что он не следовал за нами.","39":"Иисус же сказал: не препятствуйте ему: не\nможет человек сотворить чудо именем Моим и вскоре\nсказать на Меня злое.","40":"Ибо, кто не против нас, тот за нас.","41":"Ибо, кто напоит вас чашей воды ради имени\nМоего, потому что вы Христовы, истинно говорю вам: не\nпотеряет он награды своей.","42":"И кто соблазнит одного из малых сих, верующих\nв Меня, тому было бы лучше, если бы мельничный\nжернов облегал его шею, и бросили бы его в море.","43":"И если соблазнит тебя рука твоя, отруби ее:\nлучше тебе без руки войти в жизнь, чем с двумя руками\nпойти в геенну, в огонь неугасимый.","44":"Стихи 44 и 46 прежних русских переводов\nбуквально совпадают со стихом 48, но, в отличии от\nэтого\nпоследнего,\nне\nвстречаются\nв\nдревнейших\nрукописях Мк.","45":"И если нога твоя соблазняет тебя, отруби ее:\nлучше тебе войти в жизнь хромым, чем с двумя ногами\nбыть ввергнутым в геенну.","46":"Стихи 44 и 46 прежних русских переводов\nбуквально совпадают со стихом 48, но, в отличии от\nэтого\nпоследнего,\nне\nвстречаются\nв\nдревнейших\nрукописях Мк.","47":"И если глаз твой соблазняет тебя, вырви его:\nлучше тебе кривым войти в Царство Божие, чем с двумя\nглазами быть ввергнутым в геенну,","48":"где червь их не умирает, и огонь не угасает.","49":"Ибо каждый будет осолён огнем, и каждая\nжертва будет осолена солью.","50":"Соль хороша: но если соль перестанет быть\nсоленой, чем вернете вы ей силу? Имейте в себе соль и\nбудьте в мире друг с другом."},"10":{"1":"И встал Он и пошел оттуда, и приходит в область\nИудеи и по ту сторону Иордана, и снова собирается к\nНему народ, и, по Своему обыкновению, Он снова учил\nих.","2":"И подойдя, фарисеи спрашивали Его, искушая:\nможно ли мужу отпускать жену?","3":"Он ответил им: что вам заповедал Моисей?","4":"Они сказали: Моисей разрешил писать разводное\nсвидетельство и отпускать.","5":"Иисус же сказал им: по жестокосердию вашему\nнаписал он вам заповедь эту.","6":"От начала же создания Бог «мужчиною и\nженщиною сотворил их».","7":"«Поэтому оставит человек отца своего и мать","8":"и будут двое плотью единою», так что они уже не\nдва, но единая плоть.","9":"Итак, что Бог сочетал, того человек да не\nразлучает,","10":"И в доме ученики снова спрашивали Его об этом.","11":"И говорит им: кто отпустит жену свою и женится\nна другой, тот прелюбодействует по отношению к жене;","12":"и если она, покинув мужа своего, выйдет замуж\nза другого, прелюбодействует.","13":"И приносили к Нему детей, чтобы Он к ним\nприкоснулся; но ученики не позволили им.","14":"Увидев же, Иисус вознегодовал и сказал: пустите\nдетей приходить ко Мне, не препятствуйте им, ибо\nтаковых есть Царство Божие.","15":"Истинно говорю вам: кто не примет Царства\nБожия, как дитя, тот не войдет в него.","16":"И обняв их, благословил их, возложив на них\nруки.","17":"И когда выходил Он в путь, подбежал некто и,\nпреклонив перед Ним колени, спрашивал Его: Учитель\nблагой, что мне сделать, чтобы наследовать жизнь\nвечную?","18":"Иисус же сказал ему: что ты Меня называешь\nблагим? Никто не благ, кроме одного Бога.","19":"Ты\nзнаешь\nзаповеди:\n«Не\nубей,\nне\nпрелюбодействуй, не укради, не лжесвидетельствуй»,\nне обманывай, «почитай отца твоего и мать».","20":"Он же сказал Ему: Учитель, всё это я сохранил от\nюности моей.","21":"Иисус же, взглянув на него, полюбил его и сказал\nему: одного тебе недостает: иди, всё, что имеешь,\nпродай и отдай нищим, и будешь иметь сокровище на\nнебе; и приходи, следуй за Мною.","22":"Он же, омрачившись от этого слова, ушел в\nпечали: ибо владел он большим имуществом.","23":"И посмотрев вокруг, Иисус говорит ученикам\nСвоим: как трудно будет имеющим богатство войти в\nЦарство Божие.","24":"Ученики ужаснулись от слов Его. Иисус же снова\nговорит им в ответ: дети, как трудно войти в Царство\nБожие.","25":"Легче\nверблюду\nпройти\nсквозь\nигольное\nотверстие, чем богатому войти в Царство Божие.","26":"Они же чрезвычайно изумлялись, говоря между\nсобой: кто же может быть спасён?","27":"Посмотрев на них, Иисус говорит: людям это\nневозможно, но не Богу; ибо всё возможно Богу.","28":"Начал говорить Ему Петр: вот мы оставили всё и\nпоследовали за Тобою.","29":"Сказал Иисус: истинно говорю вам: нет никого,\nкто оставил дом, или братьев, или сестер, или мать, или\nотца, или детей, или земли ради Меня и ради\nЕвангелия,","30":"и не получит в сто раз больше теперь, во время\nсие, домов, и братьев, и сестер, и матерей, и детей, и\nземель, при гонениях, а в веке грядущем жизнь вечную.","31":"Многие\nже\nбудут\nпервые\nпоследними,\nи\nпоследние первыми.","32":"Были они в пути, восходя в Иерусалим, и шел\nвпереди их Иисус, и они ужасались, и сопровождающие\nбыли в страхе. И снова отозвав Двенадцать, Он начал\nговорить им о том, что предстоит Ему:","33":"вот,\nмы\nвосходим\nв\nИерусалим,\nи\nСын\nЧеловеческий\nпредан\nбудет\nпервосвященникам\nи\nкнижникам, и приговорят Его к смерти, и предадут Его\nязычникам;","34":"и надругаются над Ним, и оплюют Его, и будут\nбичевать Его, и убьют, и через три дня Он воскреснет.","35":"И подходят к Нему Иаков и Иоанн, два сына\nЗеведеева, и говорят Ему: Учитель, хотим, чтобы Ты\nсделал нам то, о чем мы Тебя попросим.","36":"Он сказал им: что вы хотите, чтобы Я сделал\nвам?","37":"Они же сказали Ему: дай нам сесть одному по\nправую Твою сторону, а другому по левую, во славе\nТвоей.","38":"Иисус же сказал им: не знаете, чего просите;\nможете ли пить чашу, которую Я пью, или крещением,\nкоторым Я крещусь, креститься?","39":"Они сказали Ему: можем. Иисус же сказал им:\nчашу, которую Я пью, будете пить, и крещением,\nкоторым Я крещусь, будете креститься;","40":"а сесть по правую Мою сторону или по левую – не\nЯ даю, но кому уготовано.","41":"И услышав, десять начали негодовать на Иакова\nи Иоанна.","42":"И призвав их, Иисус говорит им: вы знаете, что\nте, которые считаются начальниками над народами,\nгосподствуют над ними, и вельможи их показывают над\nними свою власть;","43":"но не так между вами. Но, кто хочет стать\nвеликим между вами, пусть будет вам слугой;","44":"и кто хочет между вами быть первым, пусть всем\nбудет рабом.","45":"Ибо и Сын Человеческий не для того пришел,\nчтобы Ему послужили, но чтобы послужить и дать душу\nСвою как выкуп за многих.","46":"И приходят в Иерихон. И когда выходил Он из\nИерихона, и ученики Его, и немалая толпа, – сын\nТимеев, Вартимей, слепой нищий, сидел у дороги.","47":"И услышав, что это Иисус Назарянин, он начал\nкричать и говорить: Сын Давидов, Иисус! Помилуй меня!","48":"И многие требовали от него, чтобы он замолчал,\nно тот еще больше кричал: Сын Давидов, помилуй меня!","49":"И остановившись, Иисус сказал: позовите его. И\nзовут слепого, говоря ему: дерзай, вставай, зовет тебя.","50":"Он же, сбросив верхнюю одежду, вскочил и\nподошел к Иисусу.","51":"И Иисус в ответ сказал ему: что хочешь, чтобы Я\nтебе сделал? Слепой же сказал Ему: Раввуни, чтобы я\nпрозрел.","52":"И Иисус сказал ему: иди, вера твоя спасла тебя. И\nон тотчас прозрел и последовал за Иисусом по дороге."},"11":{"1":"И когда они приближались к Иерусалиму, к\nВиффагии и Вифании, на склоне горы Масличной,\nпосылает Он двух из учеников Своих","2":"и говорит им: идите в селение, которое напротив\nвас, и тотчас при входе в него найдете осленка\nпривязанного, на которого еще никто из людей не\nсадился; отвяжите его и ведите.","3":"И если кто скажет вам: «что это вы делаете?» –\nскажите: «он нужен Господу, и Господь тотчас же\nвернет его сюда».","4":"И они пошли и нашли осленка, привязанного к\nворотам снаружи на улице, и отвязывают его.","5":"И некоторые из стоявших там говорили им: для\nчего вы отвязываете осленка?","6":"Они сказали им, как сказал Иисус; и те отпустили\nих.","7":"И приводят осленка к Иисусу, и кладут на него\nодежды свои; и Он сел на него.","8":"И многие разостлали на дороге одежды свои,\nдругие же – ветви, срезав их в полях.","9":"И шедшие впереди и следовавшие за Ним\nвосклицали: Осанна! Благословен Грядущий во имя\nГосподне!","10":"Благословенно грядущее царство отца нашего\nДавида! Осанна в вышних!","11":"И Он вошел в Иерусалим в храм и, обозрев всё,\nвышел, так как час уже был поздний, в Вифанию с\nДвенадцатью.","12":"И на другой день, когда вышли они из Вифании,\nОн проголодался;","13":"и увидев издали смоковницу, на которой были\nлистья, подошел: не найдет ли чего на ней? И подойдя\nне нашел ничего, кроме листьев; ибо не было время\nсмокв.","14":"И обратившись к ней, Он сказал: отныне да не\nвкусит никто плода от тебя вовек. И слышали это\nученики Его.","15":"И приходят в Иерусалим. И войдя в храм, начал\nОн изгонять продающих и покупающих в храме; и столы\nменял и прилавки продающих голубей опрокинул;","16":"и не позволял ничего проносить через храм;","17":"в учении Своем говорил им: не написано ли: «Дом\nМой домом молитвы будет назван для всех народов»?\nВы же сделали его вертепом разбойников.","18":"И услышали это первосвященники и книжники и\nискали, как бы Его погубить: они боялись Его, ибо весь\nнарод изумлялся Его учению.","19":"И когда наступил вечер, Он вышел из города.","20":"И проходя утром, они увидели, что смоковница\nзасохла до корня.","21":"И вспомнив, Петр говорит Ему: Равви, посмотри,\nсмоковница, которую Ты проклял, засохла.","22":"И ответил им Иисус: имейте веру в Бога.","23":"Истинно говорю вам, кто скажет горе этой:\n«поднимись и бросься в море», и не усомнится в сердце\nсвоем, но будет верить, что совершится то, что он\nговорит, – будет ему.","24":"Потому говорю вам: всё, о чем вы молитесь и\nпросите, верьте, что вы получили, – и будет вам.","25":"И когда стоите на молитве, прощайте, если что\nимеете против кого, чтобы и Отец ваш, Который на\nнебесах, простил вам согрешения ваши.","26":"Стих 26 прежних русских переводов: «если же вы\nне прощаете, то и Отец ваш, Который на небесах, не\nпростит согрешений ваших» буквально совпадающий с\nМф.6.15, отсутствует в древнейших рукописях Мк.","27":"И приходит снова в Иерусалим. И когда Он был в\nхраме, подходят к Нему первосвященники и книжники и\nстарейшины;","28":"и стали говорить Ему: какою властью Ты это\nделаешь? Или кто Тебе дал эту власть, чтобы это\nделать?","29":"Иисус же сказал им: спрошу вас об одном, и\nответьте Мне, и Я скажу вам, какою властью это делаю,","30":"Крещение Иоанново с неба было, или от людей?\nОтветьте Мне.","31":"И рассуждали между собой: если скажем «с\nнеба», Он скажет: «почему же вы не поверили ему?»","32":"Сказать же: «от людей» – боялись толпы. Ибо все\nдумали об Иоанне, что он действительно пророк,","33":"И они говорят Иисусу в ответ: не знаем. И Иисус\nговорит им: и Я вам не скажу, какою властью это делаю."},"12":{"1":"И начал говорить им притчами: насадил человек\nвиноградник и обнес стеной, и выкопал точило, и\nпостроил башню, и сдал его виноградарям, и уехал.","2":"И послал к виноградарям в свое время раба, чтобы\nвзял у виноградарей от плодов виноградника;","3":"и те, взяв его, прибили и отослали ни с чем.","4":"И снова послал к ним другого раба, и того ранили\nв голову и обесчестили.","5":"И другого послал, и того убили; и многих других –\nкому наносили побои, кого убивали.","6":"Еще один у него был: сын возлюбленный; послал\nон его последнего к ним, говоря: «устыдятся сына\nмоего».","7":"Но виноградари те сказали друг другу: «это\nнаследник: давайте, убьем его, и наследство будет\nнаше».","8":"И взяв, убили его и выбросили его вон из\nвиноградника.","9":"Что же сделает господин виноградника? Придет и\nпредаст виноградарей смерти, и отдаст виноградник\nдругим.","10":"Неужели вы и этого Писания не читали: «Камень,\nкоторый отвергли строители, он сделался главою угла:","11":"от Господа это, и удивительно в глазах наших»?","12":"И намеревались Его схватить, но побоялись\nнарода; ибо поняли, что о них сказал Он притчу; и\nоставив Его, ушли.","13":"И посылают к Нему некоторых из фарисеев и из\nиродиан, чтобы поймать Его на слове.","14":"И те, придя, говорят Ему: Учитель, мы знаем, что\nТы истинен и не считаешься ни с кем; ибо не смотришь\nна лицо людей, но воистину учишь пути Божию; можно\nли платить подать кесарю, или нет? Платить нам, или\nне платить?","15":"Он же, зная их лицемерие, сказал им: что Меня\nискушаете? Принесите Мне посмотреть динарий.","16":"Они принесли. Говорит им: чье это изображение\nи надпись? Они сказали Ему: кесаря.","17":"А Иисус сказал им: кесарево отдавайте кесарю, а\nБожие Богу. И очень удивлялись Ему.","18":"И\nприходят\nк\nНему\nсаддукеи,\nкоторые\nутверждают, что воскресения нет; и стали спрашивать\nЕго:","19":"Учитель, Моисей написал нам: «Если у кого брат\nумрет и оставит жену и не оставит детей, да возьмет\nбрат его жену и восстановит семя брату своему».","20":"Было семь братьев: и первый взял жену, и\nумирая, не оставил семени;","21":"и второй взял ее и умер, не оставив семени. И\nтретий также.","22":"И все семеро не оставили семени. После всех и\nжена умерла.","23":"В воскресение, когда воскреснут, кого из них\nбудет она женой? Ибо все семеро имели ее женой.","24":"Сказал\nим\nИисус:\nне\nпотому\nли\nвы\nзаблуждаетесь, что не знаете Писаний, ни силы\nБожией?","25":"Ведь, когда из мёртвых воскреснут, не женятся,\nи замуж не выходят, но пребывают, как ангелы на\nнебесах.","26":"О мёртвых же, что они восстают, разве не читали\nвы и книге Моисея, в повествовании о купине, как\nсказал ему Бог: «Я Бог Авраама, и Бог Исаака, и Бог\nИакова»?","27":"Он не есть Бог мёртвых, но живых. Вы весьма\nзаблуждаетесь.","28":"И подойдя, один из книжников, услышав, как они\nспорят, зная, что Он хорошо ответил им, спросил: какая\nзаповедь первая из всех?","29":"И ответил Иисус: первая есть: «Слушай, Израиль!\nГосподь Бог наш есть Господь единый;","30":"и возлюби Господа Бога твоего всем сердцем\nтвоим, и всею душою твоею, и всем разумом твоим, и\nвсею крепостию твоею».","31":"И вот вторая: «Возлюби ближнего твоего, как\nсамого себя». Нет другой заповеди большей этих.","32":"И сказал Ему книжник: хорошо, Учитель! Истинно\nТы сказал, что Он един, и нет другого, кроме Него;","33":"и любить Его всем сердцем, и всем разумением, и\nвсею крепостию, и любить ближнего, как самого себя, –\nбольше всех всесожжений и жертв.","34":"И Иисус, увидев, что он разумно отвечал, сказал\nему: недалеко ты от Царства Божия. И никто больше не\nсмел спрашивать Его.","35":"И снова говорил Иисус, уча в храме: как говорят\nкнижники, что Христос есть сын Давидов?","36":"Сам Давид сказал в Духе Святом: «Сказал\nГосподь Господу моему: сядь по правую сторону Мою,\nдоколе Я не положу врагов Твоих под ноги Твои».","37":"Сам Давид говорит, что Он – Господь: откуда же\nОн – сын его? И многолюдная толпа слушала Его охотно.","38":"И в учении Своем Он говорил: берегитесь\nкнижников, любящих длинные одежды и приветствия\nна площадях,","39":"и первые сиденья в синагогах, и первые места на\nзваных обедах.","40":"Поедающие дома вдов и для вида долго\nмолящиеся, эти примут большее осуждение.","41":"И сев напротив сокровищницы, Он смотрел, как\nнарод кладет медь в сокровищницу. И многие богатые\nклали много.","42":"И пришла одна бедная вдова и положила две\nлепты, то есть кодрант.","43":"И призвав учеников Своих, Он сказал им; истинно\nговорю вам, вдова эта бедная положила больше всех\nклавших в сокровищницу;","44":"ибо все от избытка своего положили, она же от\nскудости своей всё, что имела, положила: всё, что у нее\nбыло на жизнь."},"13":{"1":"И когда Он выходил из храма, говорит Ему один из\nучеников Его: Учитель, посмотри, какие камни и какие\nздания!","2":"И Иисус сказал ему: видишь эти великие здания?\nНе останется здесь камня на камне, который бы не был\nопрокинут.","3":"И когда сидел Он на горе Масличной напротив\nхрама, спрашивали Его отдельно от других Петр, Иаков,\nИоанн и Андрей:","4":"скажи нам, когда это будет, и какое будет\nзнамение, когда всему этому должно совершиться?","5":"Иисус же начал говорить им: смотрите, чтобы кто\nне ввел вас в заблуждение.","6":"Многие придут под именем Моим, говоря: «это Я»,\nи многих введут в заблуждение.","7":"Когда же услышите о войнах и военных слухах, не\nужасайтесь: это должно произойти, но это еще не\nконец.","8":"Ибо восстанет народ на народ и царство на\nцарство; будут землетрясения по местам, будет голод.\nЭто – начало мук рождения.","9":"Смотрите же вы за собою: будут предавать вас в\nсудилища, и в синагогах вы будете терпеть побои, и\nперед правителями и царями будете поставлены за\nМеня во свидетельство им.","10":"И во всех народах прежде должно быть\nпроповедано Евангелие,","11":"И когда будут вести вас и предавать, не\nзаботьтесь заранее, что вам сказать; но, что дано будет\nвам в тот час, то и говорите: ибо не вы будете говорить,\nно Дух Святой.","12":"И предаст брат брата на смерть, и отец дитя\nсвое; и восстанут дети на родителей и умертвят их.","13":"И будете ненавидимы всеми за имя Мое;\nпретерпевший же до конца, тот будет спасен.","14":"Когда же увидите мерзость запустения, ставшую\nгде не должно – читающий да разумеет, – тогда\nнаходящиеся в Иудее да бегут в горы;","15":"кто на крыше – да не спускается и не входит\nвзять что-либо из дома своего;","16":"и кто в поле – да не возвращается взять одежду\nсвою.","17":"Горе же имеющим во чреве и кормящим грудью в\nте дни!","18":"Молитесь, чтобы не случилось это зимой.","19":"Ибо будут дни те скорбью, какой не было от\nначала создания, которое создал Бог, доныне, и\nникогда не будет.","20":"И если бы не сократил Господь этих дней, не\nбыла бы спасена никакая плоть; но ради избранных,\nкоторых Он избрал, сократил Он эти дни.","21":"И тогда, если кто вам скажет: «вот, здесь\nХристос», «вот там», – не верьте.","22":"Восстанут лжехристы и лжепророки и сотворят\nзнамения и чудеса, чтобы вводить в заблуждение, если\nвозможно, избранных.","23":"Вы же смотрите: Я наперед сказал вам всё.","24":"Но в те дни, после скорби той, солнце померкнет,\nи луна не даст света своего,","25":"и звезды будут падать с неба, и силы небесные\nбудут поколеблены.","26":"И тогда увидят Сына Человеческого, грядущего\nна облаках с силою великою и славою.","27":"И тогда пошлет Он ангелов и соберет избранных\nСвоих от четырех ветров, от края земли до края неба.","28":"А образом да будет вам смоковница: когда ветвь\nее становится уже мягкой и пускает листья, вы знаете,\nчто близко лето;","29":"так и вы, когда увидите, что это сбывается,\nзнайте, что близко, при дверях,","30":"Истинно говорю вам: не пройдет род сей, пока\nэто всё не сбудется.","31":"Небо и земля пройдут, слова же Мои не пройдут.","32":"О дне же том или часе никто не знает, ни ангелы\nна небе, ни Сын, но только Отец.","33":"Смотрите, бодрствуйте и молитесь: ибо не знаете\nвремени.","34":"Как человек, уехавший в путешествие, оставив\nдом свой и дав рабам своим власть и каждому дело его,\n– заповедал и привратнику бодрствовать.","35":"Итак, бодрствуйте, ибо не знаете, когда придет\nгосподин дома: вечером ли, или в полночь, или в пение\nпетухов, или утром;","36":"чтобы, придя внезапно, не нашел вас спящими.","37":"И что вам говорю, всем говорю: бодрствуйте."},"14":{"1":"А через два дня была Пасха и Опресноки; и искали\nпервосвященники и книжники, как бы Его взять\nхитростью и убить;","2":"ибо они говорили: не в праздник, чтобы не было\nвозмущения в народе.","3":"И когда был Он в Вифании, в доме Симона\nпрокаженного,\nи\nвозлежал,\nпришла\nженщина\nс\nалебастровым\nсосудом\nмира\nиз\nнарда\nчистого,\nдрагоценного. Разбив сосуд, она стала возливать Ему на\nголову.","4":"Некоторые же в негодовании говорили друг другу:\nк чему эта трата мира?","5":"Ведь миро это можно было бы продать больше чем\nза\nтриста\nдинариев\nи\nдать\nнищим.\nИ\nстрого\nвыговаривали ей.","6":"Иисус же сказал: оставьте ее; что ее смущаете?\nДоброе дело сделала она Мне.","7":"Ибо нищих вы всегда имеете с собою и, когда\nхотите, можете им благотворить. Меня же не всегда\nимеете.","8":"Она сделала, что могла: заранее помазала тело\nМое для погребения.","9":"Истинно говорю вам: где ни будет проповедано\nЕвангелие во всем мире, и о том, что сделала она, будут\nговорить в воспоминание о ней.","10":"И Иуда Искариот, один из Двенадцати, пошел к\nпервосвященникам, чтобы предать Его им.","11":"Они же, услышав, обрадовались и обещали дать\nему денег. И он искал, как бы при удобном случае\nпредать Его.","12":"И в первый день Опресноков, когда закалали\nпасхального агнца, говорят Ему ученики Его: куда\nвелишь нам пойти приготовить Тебе вкусить пасху?","13":"И посылает двух из учеников Своих и говорит им:\nидите в город; и встретит вас человек с кувшином воды;\nпоследуйте за ним.","14":"И куда он войдет, скажите хозяину дома:\n«Учитель говорит: где покой Мой, в котором Я вкусил бы\nпасху с учениками Моими?»","15":"И он вам покажет горницу большую, убранную,\nготовую; там приготовьте нам.","16":"И отправились ученики Его, и пришли в город, и\nнашли, как сказал им; и приготовили пасху.","17":"И с наступлением вечера Он приходит с\nДвенадцатью.","18":"И когда возлежали они и ели, Иисус сказал:\nистинно говорю вам, один из вас предаст Меня: он ест\nсо Мною.","19":"Они начали скорбеть и говорить Ему, один за\nдругим: не я ли?","20":"Он\nже\nсказал\nим:\nодин\nиз\nДвенадцати,\nобмакивающий со Мной в одно блюдо.","21":"Ибо Сын Человеческий идет, как написано о Нем,\nно горе человеку тому, чрез которого Сын Человеческий\nпредается. Лучше было бы не родиться человеку тому.","22":"И когда они ели, Он, взяв хлеб, благословив,\nпреломил и дал им и сказал: возьмите, это есть тело\nМое.","23":"И взяв чашу, возблагодарив, дал им; и пили из\nнее все.","24":"И Он сказал им: это есть кровь Моя, кровь завета,\nизливаемая за многих.","25":"Истинно говорю вам, что не буду больше пить от\nплода лозы виноградной до того, когда буду пить его\nновым в Царстве Божием.","26":"И воспев хвалебную песнь, вышли на гору\nМасличную.","27":"И говорит им Иисус: все вы соблазнитесь, ибо\nнаписано: «Поражу пастыря, и будут рассеяны овцы»;","28":"но по восстании Моем Я предварю вас в Галилее.","29":"Петр же сказал Ему: хотя бы и все соблазнились,\nно не я.","30":"И говорит ему Иисус: истинно говорю тебе, что\nты сегодня, этой ночью, прежде чем дважды пропоет\nпетух, трижды от Меня отречешься.","31":"Он же с еще большей силой говорил: хотя бы\nнадлежало мне умереть с Тобою, не отрекусь от Тебя.\nТак же и все говорили.","32":"И приходят в местность по имени Гефсимания. И\nговорит Он ученикам Своим: посидите здесь, а Я тем\nвременем помолюсь.","33":"И берет с Собой Петра, Иакова и Иоанна. И начал\nОн ужасаться и томиться.","34":"И говорит им: объята скорбию душа Моя до\nсмерти; побудьте здесь и бодрствуйте.","35":"И пройдя немного вперед, повергался на землю и\nмолился, чтобы, если возможно, миновал Его этот час;","36":"и говорил: Авва Отче! Всё возможно Тебе;\nпронеси чашу эту мимо Меня; но не чего Я хочу, а чего\nТы.","37":"И приходит и находит их спящими, и говорит\nПетру: Симон, ты спишь? Не смог ты один час\nпободрствовать?","38":"Бодрствуйте и молитесь, чтобы не впасть в\nискушение: дух бодр, плоть же немощна.","39":"И вновь пошел и помолился и сказал то же слово.","40":"И снова придя, нашел их спящими, ибо их глаза\nотяжелели; и не знали они, что Ему ответить.","41":"И приходит в третий раз и говорит им: что же, вы\nспите\nи\nпочиваете?\nДовольно,\nпришел\nчас;\nвот,\nпредается Сын Человеческий в руки грешников.","42":"Вставайте, идем. Вот, предающий Меня близко.","43":"И тотчас, пока Он еще говорил, приходит Иуда,\nодин из Двенадцати, и с ним большая толпа с мечами и\nкольями,\nот\nпервосвященников\nи\nкнижников,\nи\nстарейшин.","44":"А предающий Его дал им условный знак, сказав:\nКого я поцелую, Он и есть; возьмите Его и ведите под\nнадежной стражей.","45":"И придя, тотчас подошел к Нему и говорит:\nРавви! и поцеловал Его.","46":"Они же наложили руки на Него и взяли Его.","47":"А один из стоявших тут, выхватив меч, ударил\nраба первосвященника и отсек ему ухо.","48":"И сказал им Иисус в ответ: как на разбойника\nвышли вы с мечами и кольями задержать Меня;","49":"каждый день бывал Я с вами в храме и учил, и вы\nне взяли Меня; но да исполнятся Писания.","50":"И оставив Его, бежали все.","51":"И некий юноша следовал за Ним, завернутый в\nпокрывало по нагому телу. И хватают его.","52":"Он же, оставив покрывало, нагой убежал.","53":"И отвели Иисуса к первосвященнику; и сходятся\nвсе первосвященники и старейшины и книжники.","54":"И Петр издали последовал за Ним, до самого\nдвора первосвященника; и сидел со служителями и\nгрелся у огня.","55":"Первосвященники же и весь синедрион искали\nпротив\nИисуса\nсвидетельства,\nчтобы предать\nЕго\nсмерти, и не находили.","56":"Ибо многие лжесвидетельствовали на Него, но\nсвидетельства эти не совпадали.","57":"И\nнекоторые\nвстав\nлжесвидетельствовали\nпротив Него, говоря:","58":"мы слышали, как Он говорил: «Я разрушу храм\nэтот, рукотворенный, и в три дня воздвигну другой,\nнерукотворенный».","59":"Но и их свидетельства не совпадали между\nсобой.","60":"И первосвященник, став посредине, спросил\nИисуса: Ты не отвечаешь ничего? Что они против Тебя\nсвидетельствуют?","61":"Он же молчал и не ответил ничего. Снова\nпервосвященник спрашивал Его и говорит Ему: Ты ли\nХристос, Сын Благословенного?","62":"Иисус же сказал: Я; и вы увидите Сына\nЧеловеческого, восседающего по правую сторону Силы\nи грядущего с облаками небесными.","63":"Первосвященник же, разодрав одежды свои,\nговорит: какая нам еще нужда в свидетелях?","64":"Вы слышали хулу! Как вам кажется? И все\nосудили Его, признав повинным смерти.","65":"И начали некоторые плевать на Него и закрывать\nЕму лицо и заушать Его и говорить Ему: прореки. И\nслужители осыпали Его ударами.","66":"И когда Петр был внизу во дворе, подходит одна\nиз служанок первосвященника","67":"и, увидев Петра греющегося и всмотревшись в\nнего, говорит: и ты с Назарянином был, с Иисусом.","68":"Но он отрекся, говоря: я не знаю и не понимаю,\nчто ты говоришь. И вышел вон на передний двор.","69":"И служанка, увидев его, начала снова говорить\nприсутствующим: этот из них.","70":"Он же стал снова отрекаться. И спустя немного,\nприсутствующие снова стали говорить Петру: поистине\nты из них; ты, ведь, и Галилеянин.","71":"Он же начал усиленно клясться: не знаю\nЧеловека Этого, о Ком говорите.","72":"И тотчас вторично пропел петух. И вспомнил\nПетр слово, сказанное ему Иисусом: прежде чем\nдважды пропоет петух, ты трижды от Меня отречешься.\nИ начал плакать."},"15":{"1":"И\nтотчас\nже\nутром\nпервосвященники\nсо\nстарейшинами и книжниками и весь синедрион вынесли\nрешение и, связав Иисуса, отвели и передали Пилату.","2":"И спросил Его Пилат: Ты Царь Иудейский? Он же\nговорит ему в ответ: ты говоришь.","3":"И первосвященники обвиняли Его много.","4":"Пилат же снова спросил Его: Ты ничего не\nотвечаешь? Смотри, как Тебя обвиняют.","5":"Но Иисус и на это ничего не ответил, так что\nПилат удивлялся.","6":"На Праздник же отпускал он им одного узника,\nкоторого они себе выпрашивали.","7":"Был тогда в узах человек, называемый Варавва,\nвместе с повстанцами, которые, во время восстания,\nсовершили убийство.","8":"И поднявшись наверх, толпа начала просить\nПилата о том, что он обычно делал для них.","9":"Пилат же ответил им: хотите, я отпущу вам Царя\nИудейского?","10":"Ибо знал он, что первосвященники предали Его\nиз зависти.","11":"Но первосвященники возбудили толпу, чтобы он\nотпустил им лучше Варавву.","12":"Пилат же снова отвечал им: что же мне делать с\nТем, Кого вы называете Царем Иудейским?","13":"Они снова закричали: распни Его!","14":"Пилат же говорил им: какое же Он сделал зло? А\nони еще сильнее закричали: распни Его!","15":"И Пилат, желая угодить толпе, отпустил им\nВаравву, и предал Иисуса, по бичевании, на распятие.","16":"Воины отвели Его внутрь двора, то есть в\nпреторию. И созывают всю когорту,","17":"и одевают Его в пурпур и, сплетя терновый\nвенец, надевают на Него.","18":"И начали приветствовать Его: да здравствует\nЦарь Иудейский!","19":"И били Его по голове тростью, и плевали на Него\nи, опускаясь на колени, поклонялись Ему.","20":"Когда же надругались над Ним, сняли с Него\nпурпур и одели Его в одежды Его. И выводят Его, чтобы\nраспять Его.","21":"И\nзаставляют\nнекоего\nпрохожего,\nСимона\nКиринеянина, идущего с поля, отца Александра и Руфа,\nвзять крест Его.","22":"И приводят Его на место Голгофу, что значит в\nпереводе: «Лобное место».","23":"И давали Ему вино со смирной; но Он не принял.","24":"И распинают Его и делят между собой одежды\nЕго, бросая о них жребий, кому что взять.","25":"Был же час третий, когда распяли Его.","26":"И стояло обозначение вины Его в надписи: Царь\nИудейский.","27":"И с Ним распинают двух разбойников, одного\nсправа и другого слева от Него.","28":"Стих\n28\nпрежних\nрусских\nпереводов:\n«и\nисполнилось\nПисание,\nкоторое\nговорит:\nи\nк\nбеззаконным причтен» совпадающий во второй своей\nчасти с Лк.22.37, отсутствует в древнейших рукописях\nМк.","29":"И прохожие хулили Его, кивая головами своими и\nговоря: О, Разрушающий храм и Воздвигающий в три\nдня!","30":"Спаси Себя Самого, сойди с креста.","31":"Подобным\nобразом\nи\nпервосвященники,\nиздеваясь вместе с книжниками, говорили друг другу:\nдругих спас, Себя Самого не может спасти!","32":"Христос, Царь Израилев, пусть сойдет теперь с\nкреста, чтобы мы увидели и уверовали. И распятые с\nНим поносили Его.","33":"И когда настал час шестой, тьма наступила по\nвсей земле до часа девятого.","34":"И в девятом часу возопил Иисус громким\nголосом: Элои, Элои! лама савахфани? что в переводе\nзначит: Боже Мой, Боже Мой! Зачем оставил Ты Меня?","35":"И\nнекоторые\nиз\nстоявших\nтут,\nуслышав,\nговорили: вот, Илию зовет.","36":"А кто-то побежал, наполнил губку уксусом и,\nнаткнув на трость, давал Ему пить, говоря: оставьте,\nпосмотрим, придет ли Илия снять Его.","37":"Иисус же, воззвав громким голосом, испустил\nпоследний вздох.","38":"И завеса храма разорвалась надвое, сверху\nдонизу.","39":"А сотник, стоявший тут напротив Него, увидев,\nчто Он, так возгласив, испустил последний вздох,\nсказал: воистину Этот Человек был Сын Божий.","40":"Смотрели издали и женщины; между ними и\nМария Магдалина, и Мария, мать Иакова Меньшего и\nИосита, и Саломия,","41":"те, которые следовали за Ним и служили Ему,\nкогда Он был в Галилее, и другие многие, пришедшие\nвместе с Ним в Иерусалим.","42":"И уже вечером, так как это была пятница, то есть\nканун субботы,","43":"пришел Иосиф из Аримафеи, видный член совета,\nкоторый и сам пребывал в ожидании Царства Божия. Он\nосмелился войти к Пилату и попросил тело Иисуса.","44":"Пилат удивился, что Он уже мертв; и призвав\nсотника, спросил его: давно ли Он умер?","45":"И узнав от сотника, даровал тело Иосифу.","46":"И купив полотно, он снял Его, обвил полотном и\nположил Его в гробницу, которая была высечена в\nскале; и привалил камень ко входу в гробницу.","47":"Мария\nже\nМагдалина\nи\nМария\nИоситова\nсмотрели, где Он был положен."},"16":{"1":"И по прошествии субботы, Мария Магдалина и\nМария Иаковлева и Саломия купили благовония, чтобы\nпойти помазать Его.","2":"И ранним утром, в первый день недели, приходят\nк гробнице, по восходе солнца;","3":"и говорили они между собой: кто отвалит нам\nкамень от входа в гробницу?","4":"И посмотрев, видят, что камень отвален; а был он\nвесьма велик.","5":"И войдя в гробницу, они увидели, что с правой\nстороны сидит юноша, облеченный в одеяние белое; и\nужаснулись.","6":"Он же говорит им: не ужасайтесь. Иисуса ищете\nНазарянина, распятого; Он восстал. Его нет здесь. Вот\nместо, где положили Его.","7":"Но идите, скажите ученикам Его и Петру, что Он\nпредваряет вас в Галилее; там вы Его увидите, как Он\nсказал вам.","8":"И выйдя, они побежали от гробницы, владел ими\nтрепет и исступление, и никому ничего не сказали: ибо\nони боялись.","9":"Стихи 9–20 отсутствуют в древнейших рукописях\nМк. Воскресши же рано в первый день недели, Он\nявился сперва Марии Магдалине, из которой изгнал\nсемь бесов,","10":"Стихи 9–20 отсутствуют в древнейших рукописях\nМк. Она пошла и возвестила бывшим с Ним, когда те\nбыли в скорби и слезах;","11":"Стихи 9–20 отсутствуют в древнейших рукописях\nМк. и они, услышав, что Он жив, и что она видела Его,\nне поверили.","12":"Стихи 9–20 отсутствуют в древнейших рукописях\nМк. После же этого явился в другом образе двум из них\nна пути, когда они шли в селение.","13":"Стихи 9–20 отсутствуют в древнейших рукописях\nМк. И они пошли и возвестили остальным; но не\nповерили и им.","14":"Стихи 9–20 отсутствуют в древнейших рукописях\nМк. Наконец явился и самим одиннадцати, когда они\nвозлежали, и укорил их за неверие и жестокосердие,\nчто тем, кто видели Его восставшим, не поверили.","15":"Стихи 9–20 отсутствуют в древнейших рукописях\nМк. И сказал им: идите по всему миру и проповедайте\nЕвангелие всей твари.","16":"Стихи 9–20 отсутствуют в древнейших рукописях\nМк.\nУверовавший\nи\nкрещенный\nбудет\nспасен,\nа\nнеповеривший будет осужден.","17":"Стихи 9–20 отсутствуют в древнейших рукописях\nМк. И вот те знамения, которые будут сопровождать\nуверовавших: именем Моим будут изгонять бесов, будут\nговорить на новых языках;","18":"Стихи 9–20 отсутствуют в древнейших рукописях\nМк. будут брать змей; хотя бы и смертоносное что\nвыпили, не повредит им; на больных будут возлагать\nруки, и они будут здоровы.","19":"Стихи 9–20 отсутствуют в древнейших рукописях\nМк. Итак, Господь Иисус после беседы с ними вознесся\nна небо и сел по правую сторону Бога.","20":"Стихи 9–20 отсутствуют в древнейших рукописях\nМк. Они же, выйдя, проповедали повсюду: Господь им\nсодействовал\nи\nутверждал\nслово\nпоследующими\nзнамениями."}};
